# =====================================================================
#  Deploy-And-Publish.ps1  -  build: 2026-07-05 v2 (GUI + rounded + logo)
#  Greg Blair / GNL Digital Group
#
#  WHAT IT DOES  (one button, files to live)
#    1. Rounded borderless window with logo on top.
#    2. Pick the repo from a dropdown.
#    3. Copies everything in C:\Github\files into that repo (mirrors
#       the folder tree), overwriting silently.
#    4. git add -A -> git commit -> git push to the repo's CURRENT
#       branch (main, master, whatever it actually is).
#    5. Empties C:\Github\files.
#    6. Popup tells you it pushed, or shows the error.
#
#  AUTH: uses Git Credential Manager (ships with Git for Windows).
#        First push opens a browser sign-in once, then cached forever.
#        No GitHub Desktop required.
# =====================================================================

# ---- Config: the only two paths you'd ever change -------------------
$ReposRoot = "C:\Github"          # repos live directly in here
$FilesRoot = "C:\Github\files"    # you drop files to deploy in here
# --------------------------------------------------------------------

$ExcludeFolders = @("files")

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

function Show-Error($msg) {
    [System.Windows.Forms.MessageBox]::Show($msg, "Deploy & Publish - Error",
        [System.Windows.Forms.MessageBoxButtons]::OK,
        [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
}
function Show-Info($msg) {
    [System.Windows.Forms.MessageBox]::Show($msg, "Deploy & Publish",
        [System.Windows.Forms.MessageBoxButtons]::OK,
        [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
}

# --- Sanity checks ---------------------------------------------------
if (-not (Test-Path $ReposRoot)) { Show-Error "Repos folder not found:`n$ReposRoot"; exit 1 }
if (-not (Test-Path $FilesRoot)) {
    # auto-create the staging folder if it's missing
    try { New-Item -ItemType Directory -Path $FilesRoot -Force | Out-Null }
    catch { Show-Error "Files folder not found and could not be created:`n$FilesRoot"; exit 1 }
}

$repos = Get-ChildItem -Path $ReposRoot -Directory |
    Where-Object { $ExcludeFolders -notcontains $_.Name } |
    Sort-Object Name
if ($repos.Count -eq 0) { Show-Error "No repos found in:`n$ReposRoot"; exit 1 }

