function Get-LogoImage {
    try {
        $bytes = [Convert]::FromBase64String(($logoB64 -replace "\s",""))
        $ms = New-Object System.IO.MemoryStream(,$bytes)
        return [System.Drawing.Image]::FromStream($ms)
    } catch { return $null }
}
$logoImg = Get-LogoImage

# =====================================================================
#  ROUNDED-CORNER HELPER
# =====================================================================
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class NativeRegion {
    [DllImport("gdi32.dll", SetLastError=true)]
    public static extern IntPtr CreateRoundRectRgn(int x1,int y1,int x2,int y2,int cx,int cy);
    [DllImport("user32.dll", SetLastError=true)]
    public static extern int SetWindowRgn(IntPtr hWnd, IntPtr hRgn, bool bRedraw);
}
"@

# =====================================================================
#  BUILD THE WINDOW
# =====================================================================
$W = 380
$H = 470
$radius = 28

$form = New-Object System.Windows.Forms.Form
$form.Text = "Deploy & Publish"
$form.Size = New-Object System.Drawing.Size($W, $H)
$form.StartPosition = "CenterScreen"
$form.FormBorderStyle = "None"          # borderless -> we draw rounded ourselves
$form.MaximizeBox = $false
$form.MinimizeBox = $false
$form.BackColor = [System.Drawing.Color]::FromArgb(245,247,250)
$form.Add_Shown({
    $rgn = [NativeRegion]::CreateRoundRectRgn(0,0,$form.Width,$form.Height,$radius,$radius)
    [NativeRegion]::SetWindowRgn($form.Handle,$rgn,$true) | Out-Null
})

# --- make the window draggable (no title bar) ---
$script:drag=$false; $script:dx=0; $script:dy=0
$dragDown = { param($s,$e) $script:drag=$true; $script:dx=$e.X; $script:dy=$e.Y }
$dragMove = { param($s,$e)
    if ($script:drag) {
        $form.Left += ($e.X - $script:dx)
        $form.Top  += ($e.Y - $script:dy)
    }
}
$dragUp = { $script:drag=$false }

# --- top accent bar (draggable) ---
$bar = New-Object System.Windows.Forms.Panel
$bar.Size = New-Object System.Drawing.Size($W, 6)
$bar.Location = New-Object System.Drawing.Point(0,0)
$bar.BackColor = [System.Drawing.Color]::FromArgb(212,160,23)   # gold
$form.Controls.Add($bar)

# --- close button (top-right X) ---
$btnClose = New-Object System.Windows.Forms.Label
$btnClose.Text = [char]0x2715   # X
$btnClose.Font = New-Object System.Drawing.Font("Segoe UI",11,[System.Drawing.FontStyle]::Bold)
$btnClose.ForeColor = [System.Drawing.Color]::Gray
$btnClose.Size = New-Object System.Drawing.Size(28,26)
$btnClose.Location = New-Object System.Drawing.Point(($W-34),10)
$btnClose.TextAlign = "MiddleCenter"
$btnClose.Cursor = "Hand"
$btnClose.Add_Click({ $form.Close() })
$btnClose.Add_MouseEnter({ $btnClose.ForeColor=[System.Drawing.Color]::FromArgb(200,40,40) })
$btnClose.Add_MouseLeave({ $btnClose.ForeColor=[System.Drawing.Color]::Gray })
$form.Controls.Add($btnClose)

# --- logo ---
$pic = New-Object System.Windows.Forms.PictureBox
$logoW = 210
if ($logoImg) {
    $ratio = $logoImg.Height / $logoImg.Width
    $logoH = [int]($logoW * $ratio)
} else { $logoH = 190 }
$pic.Size = New-Object System.Drawing.Size($logoW,$logoH)
$pic.Location = New-Object System.Drawing.Point(([int](($W-$logoW)/2)),18)
$pic.SizeMode = "Zoom"
$pic.BackColor = [System.Drawing.Color]::Transparent
if ($logoImg) { $pic.Image = $logoImg }
$pic.Add_MouseDown($dragDown); $pic.Add_MouseMove($dragMove); $pic.Add_MouseUp($dragUp)
$form.Controls.Add($pic)

$y = 18 + $logoH + 10

# --- Repository label ---
$lblRepo = New-Object System.Windows.Forms.Label
$lblRepo.Text = "Repository"
$lblRepo.Font = New-Object System.Drawing.Font("Segoe UI",9,[System.Drawing.FontStyle]::Bold)
$lblRepo.ForeColor = [System.Drawing.Color]::FromArgb(70,80,95)
$lblRepo.Location = New-Object System.Drawing.Point(30,$y)
$lblRepo.Size = New-Object System.Drawing.Size(320,18)
$form.Controls.Add($lblRepo)
$y += 20

# --- Repo dropdown ---
$ddRepo = New-Object System.Windows.Forms.ComboBox
$ddRepo.DropDownStyle = "DropDownList"
$ddRepo.Font = New-Object System.Drawing.Font("Segoe UI",10)
$ddRepo.Location = New-Object System.Drawing.Point(30,$y)
$ddRepo.Size = New-Object System.Drawing.Size(($W-60),26)
foreach ($r in $repos) { [void]$ddRepo.Items.Add($r.Name) }
$ddRepo.SelectedIndex = 0
$form.Controls.Add($ddRepo)
$y += 34

# --- staged count ---
$lblCount = New-Object System.Windows.Forms.Label
$lblCount.Location = New-Object System.Drawing.Point(30,$y)
$lblCount.Size = New-Object System.Drawing.Size(($W-60),18)
$staged = Get-ChildItem -Path $FilesRoot -Recurse -File -ErrorAction SilentlyContinue
$lblCount.Text = "$($staged.Count) file(s) staged in C:\Github\files"
$lblCount.Font = New-Object System.Drawing.Font("Segoe UI",8)
$lblCount.ForeColor = [System.Drawing.Color]::DimGray
$form.Controls.Add($lblCount)
$y += 24

# --- commit message label ---
$lblMsg = New-Object System.Windows.Forms.Label
$lblMsg.Text = "Commit message"
$lblMsg.Font = New-Object System.Drawing.Font("Segoe UI",9,[System.Drawing.FontStyle]::Bold)
$lblMsg.ForeColor = [System.Drawing.Color]::FromArgb(70,80,95)
$lblMsg.Location = New-Object System.Drawing.Point(30,$y)
$lblMsg.Size = New-Object System.Drawing.Size(320,18)
$form.Controls.Add($lblMsg)
$y += 20

# --- commit box ---
$txtMsg = New-Object System.Windows.Forms.TextBox
$txtMsg.Font = New-Object System.Drawing.Font("Segoe UI",10)
$txtMsg.Location = New-Object System.Drawing.Point(30,$y)
$txtMsg.Size = New-Object System.Drawing.Size(($W-60),26)
$txtMsg.Text = "Deploy " + (Get-Date -Format "yyyy-MM-dd HH:mm")
$form.Controls.Add($txtMsg)
$y += 40

# --- Deploy & Publish button ---
$btn = New-Object System.Windows.Forms.Button
$btn.Text = "Deploy && Publish"
$btn.Location = New-Object System.Drawing.Point(30,$y)
$btn.Size = New-Object System.Drawing.Size(($W-60),52)
$btn.Font = New-Object System.Drawing.Font("Segoe UI",13,[System.Drawing.FontStyle]::Bold)
$btn.FlatStyle = "Flat"
$btn.FlatAppearance.BorderSize = 0
$btn.BackColor = [System.Drawing.Color]::FromArgb(34,139,69)   # green
$btn.ForeColor = [System.Drawing.Color]::White
$btn.Cursor = "Hand"
$btn.Add_MouseEnter({ $btn.BackColor=[System.Drawing.Color]::FromArgb(40,160,80) })
$btn.Add_MouseLeave({ $btn.BackColor=[System.Drawing.Color]::FromArgb(34,139,69) })
# round the button too
$btn.Add_Paint({
    $gp = New-Object System.Drawing.Drawing2D.GraphicsPath
    $r = 12; $bw=$btn.Width; $bh=$btn.Height
    $gp.AddArc(0,0,$r,$r,180,90)
    $gp.AddArc(($bw-$r),0,$r,$r,270,90)
    $gp.AddArc(($bw-$r),($bh-$r),$r,$r,0,90)
    $gp.AddArc(0,($bh-$r),$r,$r,90,90)
    $gp.CloseAllFigures()
    $btn.Region = New-Object System.Drawing.Region($gp)
})
$form.Controls.Add($btn)
$y += 60

# --- status line ---
$lblStatus = New-Object System.Windows.Forms.Label
$lblStatus.Location = New-Object System.Drawing.Point(30,$y)
$lblStatus.Size = New-Object System.Drawing.Size(($W-60),18)
$lblStatus.Font = New-Object System.Drawing.Font("Segoe UI",8)
$lblStatus.ForeColor = [System.Drawing.Color]::DimGray
$lblStatus.TextAlign = "MiddleCenter"
$form.Controls.Add($lblStatus)

# background is draggable too
$form.Add_MouseDown($dragDown); $form.Add_MouseMove($dragMove); $form.Add_MouseUp($dragUp)
$bar.Add_MouseDown($dragDown);  $bar.Add_MouseMove($dragMove);  $bar.Add_MouseUp($dragUp)

# =====================================================================
#  BUTTON ACTION
# =====================================================================
$btn.Add_Click({
    $btn.Enabled = $false
    $lblStatus.Text = "Working..."
    $form.Refresh()

    try {
        $targetName = $ddRepo.SelectedItem.ToString()
        $targetRepo = Join-Path $ReposRoot $targetName

        $files = Get-ChildItem -Path $FilesRoot -Recurse -File -ErrorAction SilentlyContinue
        if ($files.Count -eq 0) {
            Show-Error "Nothing to deploy - C:\Github\files is empty."
            $btn.Enabled = $true; $lblStatus.Text = ""
            return
        }

        # 1. Copy, mirroring the tree
        foreach ($file in $files) {
            $relative = $file.FullName.Substring($FilesRoot.Length).TrimStart('\')
            $destination = Join-Path $targetRepo $relative
            $destDir = Split-Path $destination -Parent
            if (-not (Test-Path $destDir)) {
                New-Item -ItemType Directory -Path $destDir -Force | Out-Null
            }
            Copy-Item -Path $file.FullName -Destination $destination -Force
        }

        # 2. git add / commit / push (current branch)
        Push-Location $targetRepo
        try {
            $inside = (& git rev-parse --is-inside-work-tree 2>$null)
            if ($LASTEXITCODE -ne 0 -or $inside -ne "true") {
                throw "$targetName is not a git repository (no .git found)."
            }
            $branch = (& git rev-parse --abbrev-ref HEAD 2>$null).Trim()
            if ([string]::IsNullOrWhiteSpace($branch)) { $branch = "main" }

            & git add -A 2>&1 | Out-Null

            & git diff --cached --quiet 2>$null
            if ($LASTEXITCODE -eq 0) {
                Show-Info "Files copied into $targetName, but there was nothing new to commit`n(the files matched what's already in the repo)."
                Get-ChildItem -Path $FilesRoot -Force | Remove-Item -Recurse -Force
                $lblCount.Text = "0 file(s) staged in C:\Github\files"
                $btn.Enabled = $true; $lblStatus.Text = ""
                return
            }

            $commitMsg = $txtMsg.Text
            if ([string]::IsNullOrWhiteSpace($commitMsg)) {
                $commitMsg = "Deploy " + (Get-Date -Format "yyyy-MM-dd HH:mm")
            }

            $commitOut = (& git commit -m $commitMsg 2>&1)
            if ($LASTEXITCODE -ne 0) { throw "git commit failed:`n$commitOut" }

            $pushOut = (& git push origin $branch 2>&1)
            if ($LASTEXITCODE -ne 0) { throw "git push failed:`n$pushOut" }
        }
        finally { Pop-Location }

        # 3. Clear staging
        Get-ChildItem -Path $FilesRoot -Force | Remove-Item -Recurse -Force
        $lblCount.Text = "0 file(s) staged in C:\Github\files"

        Show-Info "Pushed to '$branch' in $targetName.`n`n$($files.Count) file(s) deployed. You're live."
        $lblStatus.Text = "Done."
    }
    catch {
        Show-Error $_.Exception.Message
        $lblStatus.Text = "Error - nothing pushed."
    }
    finally { $btn.Enabled = $true }
})

$ddRepo.Add_SelectedIndexChanged({
    $s = Get-ChildItem -Path $FilesRoot -Recurse -File -ErrorAction SilentlyContinue
    $lblCount.Text = "$($s.Count) file(s) staged in C:\Github\files"
})

[void]$form.ShowDialog()
